#!/usr/bin/env bash
set -e

if [ -f debug.keystore.base64 ]; then
  echo "Restoring from debug.keystore.base64..."
  cat debug.keystore.base64 | tr -d '\r\n ' | base64 -d > debug.keystore
elif [ -n "${DEBUG_KEYSTORE_BASE64}" ]; then
  echo "Restoring from environment variable..."
  echo "${DEBUG_KEYSTORE_BASE64}" | tr -d '\r\n ' | base64 -d > debug.keystore
fi

if [ ! -s debug.keystore ]; then
  echo "Restoring from embedded verified keystore..."
  echo "" | base64 -d > debug.keystore
fi

keytool -list -v -keystore debug.keystore -alias androiddebugkey -storepass android -keypass android | grep -E "SHA1|SHA256"
